import { SOCIAL_API, IDENTITY_API } from '../../../shared/config/services.js';
import { apiRequest } from '../../../shared/api/request.js';
import { File } from 'expo-file-system';

const recentViewRequests = new Map();

// The cursor is an opaque value generated by the Social service.
export async function getFeed(token, cursor, signal, mode = 'network') {
    const query = new URLSearchParams({ cursor: cursor || '', limit: '10', mode });
    const result = await apiRequest(SOCIAL_API, `/feed?${query}`, { token, signal });
    if (!Array.isArray(result.data) || !result.pagination) throw new Error('Unexpected feed response.');
    return result;
}

export async function getDisplayUser(token, id, signal) {
    try {
        const result = await apiRequest(IDENTITY_API, `/users/${id}/profile`, { token, signal });
        return result.data;
    } catch (error) {
        if (error.status === 404) return { id, name: 'Unavailable account', username: null };
        throw error;
    }
}

export function getMediaUrl(postId, mediaId) {
    return `${SOCIAL_API}/posts/${postId}/media/${mediaId}`;
}

export function getMediaThumbnailUrl(postId, mediaId) {
    return `${getMediaUrl(postId, mediaId)}/thumbnail`;
}

export function getUserPosts(token, userId, signal, page = 1, type = 'all') {
    return apiRequest(SOCIAL_API, `/profiles/${userId}/posts?page=${page}&limit=20&type=${type}`, { token, signal });
}

export function getUserReshares(token, userId, signal, page = 1) {
    return apiRequest(SOCIAL_API, `/profiles/${userId}/reshares?page=${page}&limit=20`, { token, signal });
}

export async function createPost(token, content, signal) {
    const result = await apiRequest(SOCIAL_API, '/posts', {
        token,
        method: 'POST',
        body: { content, kind: 'post' },
        signal,
    });
    return result.data;
}

export async function updatePost(token, postId, content) {
    const result = await apiRequest(SOCIAL_API, `/posts/${postId}`, { token, method: 'PATCH', body: { content } });
    return result.data;
}

export const deletePost = (token, postId) => apiRequest(SOCIAL_API, `/posts/${postId}`, { token, method: 'DELETE' });

export async function getSavedPostState(token, postId, signal) {
    const result = await apiRequest(SOCIAL_API, `/posts/${postId}/saved`, { token, signal });
    return Boolean(result.data?.saved);
}

export async function savePost(token, postId) {
    const result = await apiRequest(SOCIAL_API, `/posts/${postId}/saved`, { token, method: 'PUT', body: {} });
    return result.data;
}

export const unsavePost = (token, postId) => apiRequest(SOCIAL_API, `/posts/${postId}/saved`, { token, method: 'DELETE' });

export async function getSavedPosts(token, signal) {
    const result = await apiRequest(SOCIAL_API, '/saved-posts', { token, signal });
    if (!Array.isArray(result.data)) throw new Error('Unexpected saved moments response.');
    return result.data;
}

export async function createMediaPost(token, content, assets, kind = 'post') {
    const form = new FormData();
    form.append('content', content);
    form.append('kind', kind);
    for (const [index, asset] of assets.entries()) {
        const extension = (asset.fileName?.split('.').pop()?.toLowerCase() || '').replace(/[^a-z0-9]/g, '');
        const isVideo = asset.type === 'video' || asset.mimeType?.startsWith('video/') || ['mp4', 'webm'].includes(extension);
        const mimeByExtension = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', mp4: 'video/mp4', webm: 'video/webm' };
        const mimeType = asset.mimeType?.toLowerCase() || mimeByExtension[extension] || (isVideo ? 'video/mp4' : 'image/jpeg');
        if (!asset.uri) throw new Error('A selected media file is missing its local URI. Select it again.');
        if (!mimeByExtension[extension] && !asset.mimeType && !(isVideo && asset.type === 'video')) throw new Error('WindChime could not identify this file type. Choose a JPG, PNG, WebP, MP4, or WebM file.');
        const file = new File(asset.uri);
        const filename = asset.fileName || `windchime-${Date.now()}-${index}.${mimeType.split('/')[1] === 'jpeg' ? 'jpg' : mimeType.split('/')[1]}`;
        form.append('media', file, filename);
        if (asset.thumbnailUri) {
            const thumbnail = new File(asset.thumbnailUri);
            const signature = new Uint8Array(await thumbnail.slice(0, 16).arrayBuffer());
            const isPng = signature.length >= 8 && signature[0] === 137 && signature[1] === 80 && signature[2] === 78 && signature[3] === 71;
            const isWebp = signature.length >= 12 && String.fromCharCode(...signature.slice(0, 4)) === 'RIFF' && String.fromCharCode(...signature.slice(8, 12)) === 'WEBP';
            const isJpeg = signature.length >= 3 && signature[0] === 255 && signature[1] === 216 && signature[2] === 255;
            if (!isPng && !isWebp && !isJpeg) throw new Error('The Reel preview image could not be read. Try selecting the video again.');
            const thumbnailType = isPng ? 'image/png' : isWebp ? 'image/webp' : 'image/jpeg';
            const thumbnailName = `windchime-poster-${Date.now()}.${thumbnailType.split('/')[1] === 'jpeg' ? 'jpg' : thumbnailType.split('/')[1]}`;
            form.append('thumbnail', thumbnail, thumbnailName);
        }
    }
    const result = await apiRequest(SOCIAL_API, '/posts', { token, method: 'POST', body: form, timeoutMs: 120000 });
    return result.data;
}

export async function getPostSummary(token, postId, signal) {
    const [reaction, comments, repost, views] = await Promise.all([
        apiRequest(SOCIAL_API, `/posts/${postId}/reactions/summary`, { token, signal }),
        apiRequest(SOCIAL_API, `/posts/${postId}/comments/summary`, { token, signal }),
        apiRequest(SOCIAL_API, `/posts/${postId}/repost`, { token, signal }),
        apiRequest(SOCIAL_API, `/posts/${postId}/views`, { token, signal }),
    ]);
    return {
        reaction: reaction.data,
        comments: comments.data,
        repost: repost.data,
        views: views.data,
    };
}

function insightEventKey(eventType) {
    if (eventType === 'view') return `view_${Math.floor(Date.now() / (30 * 60 * 1000))}`;
    return `${Date.now()}_${Math.random().toString(36).slice(2, 14)}`;
}

export function recordPostInsight(token, postId, eventType, source = 'feed') {
    return apiRequest(SOCIAL_API, `/posts/${postId}/insights/events`, {
        token,
        method: 'POST',
        body: { event_type: eventType, source, event_key: insightEventKey(eventType) },
    });
}

export async function getPostInsights(token, postId, signal) {
    const result = await apiRequest(SOCIAL_API, `/posts/${postId}/insights`, { token, signal });
    return result.data;
}

export async function recordPostView(token, postId, source = 'feed') {
    const key = `${token}:${postId}`;
    const now = Date.now();
    const lastView = recentViewRequests.get(key);
    if (lastView && now - lastView < 30 * 60 * 1000) return null;
    recentViewRequests.set(key, now);
    try {
        await recordPostInsight(token, postId, 'view', source);
        const views = await apiRequest(SOCIAL_API, `/posts/${postId}/views`, { token });
        return views.data;
    } catch (error) {
        recentViewRequests.delete(key);
        throw error;
    }
}

export const setPostReaction = (token, postId, type = 'like') => apiRequest(
    SOCIAL_API,
    `/posts/${postId}/reactions`,
    { token, method: 'PUT', body: { type } },
);

export const removePostReaction = (token, postId) => apiRequest(
    SOCIAL_API,
    `/posts/${postId}/reactions`,
    { token, method: 'DELETE' },
);

export const setRepost = (token, postId) => apiRequest(
    SOCIAL_API,
    `/posts/${postId}/repost`,
    { token, method: 'PUT', body: {} },
);

export const removeRepost = (token, postId) => apiRequest(
    SOCIAL_API,
    `/posts/${postId}/repost`,
    { token, method: 'DELETE' },
);

export async function getPostComments(token, postId, signal, parentId = null) {
    const query = new URLSearchParams({ page: '1', limit: '50', ...(parentId ? { parent_id: String(parentId) } : {}) });
    return apiRequest(SOCIAL_API, `/posts/${postId}/comments?${query}`, { token, signal });
}

export async function getCommentSummary(token, postId, signal) {
    return apiRequest(SOCIAL_API, `/posts/${postId}/comments/summary`, { token, signal });
}

export async function addPostComment(token, postId, content, parentId = null) {
    const result = await apiRequest(SOCIAL_API, `/posts/${postId}/comments`, {
        token,
        method: 'POST',
        body: { content, parent_id: parentId },
    });
    return result.data;
}
